    res = [[0]*n for _ in range(n)]
    for i in range(n):
        ai = a[i]
        ri = res[i]
        for k in range(n):
            if ai[k]:
                aik = ai[k]
                bk = b[k]
                for j in range(n):
                    ri[j] = (ri[j] + aik * bk[j]) % MOD
    return res

def mat_pow(mat, power):
    n = len(mat)
    # identity
    res = [[0]*n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1
    while power:
        if power & 1:
            res = mat_mul(res, mat)
        mat = mat_mul(mat, mat)
        power >>= 1
    return res

def main():
