    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    words = [next(it).strip() for _ in range(n)]
    maxL = 5

    # dp_len[l][i]: number of ways to cover length l ending at state i (0..maxL-1)
    dp_len = [[0]*maxL for _ in range(maxL+1)]
    dp_len[0][0] = 1
    for l in range(1, maxL+1):
        for i in range(maxL):
            val = 0
            for w in words:
