                if k <= l:
                    prev = (i - k) % maxL
                    val += dp_len[l-k][prev]
            dp_len[l][i] = val % MOD

    # transition matrix T of size maxL x maxL
    T = [[0]*maxL for _ in range(maxL)]
    for i in range(maxL):
        for w in words:
            k = len(w)
            j = (i + k) % maxL
            T[i][j] = (T[i][j] + 1) % MOD

    if m <= maxL:
        ans = 0
        for l in range(1, m+1):
            for i in range(maxL):
                ways = dp_len[l][i]
                if ways:
                    ans = (ans + ways * ways) % MOD
        print(ans)
        return

    # prefix up to maxL
    ans = 0
    for l in range(1, maxL+1):
        for i in range(maxL):
            ways = dp_len[l][i]
            if ways:
                ans = (ans + ways * ways) % MOD

    # matrix exponentiation for remaining part
    power = m - maxL
    Tpow = mat_pow(T, power)

    # initial vector v: dp_len[maxL]
    v = dp_len[maxL]

    # compute v * Tpow
    res = [0]*maxL
    for j in range(maxL):
        s = 0
        for i in range(maxL):
            s = (s + v[i] * Tpow[i][j]) % MOD
        res[j] = s

    # add contributions for lengths > maxL
    # For each state j, number of ways to cover length m ending at j is res[j]
    for j in range(maxL):
        ans = (ans + res[j] * res[j]) % MOD

    print(ans)

