import sys

MOD = 998244353

def mat_mul(a, b):
    n = len(a)
    res = [[0]*n for _ in range(n)]
    for i in range(n):
        ai = a[i]
        ri = res[i]
        for k in range(n):
            if ai[k]:
                aik = ai[k]
                bk = b[k]
                for j in range(n):
                    ri[j] = (ri[j] + aik * bk[j]) % MOD
    return res

def mat_pow(mat, power):
    n = len(mat)
    # identity
    res = [[0]*n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1
    base = mat
    while power:
        if power & 1:
            res = mat_mul(res, base)
        base = mat_mul(base, base)
        power >>= 1
    return res

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    words = [next(it).strip() for _ in range(n)]
    maxL = 5

    # Precompute lengths and first letters
    lens = [len(w) for w in words]
    first = [w[0] for w in words]

    # Precompute for each word its prefix lengths that are also words
    # and suffix lengths that are also words
    # Also map (length, first_char) -> list of word indices
    pref = [[] for _ in range(n)]
    suff = [[] for _ in range(n)]
    by_len_char = {}
    for i, w in enumerate(words):
        L = len(w)
        for j in range(1, L+1):
            sub = w[:j]
            for k, ww in enumerate(words):
                if ww == sub:
                    pref[i].append(j)
                    break
        for j in range(1, L+1):
            sub = w[L-j:]
            for k, ww in enumerate(words):
                if ww == sub:
                    suff[i].append(j)
                    break
        key = (L, w[0])
        by_len_char.setdefault(key, []).append(i)

    # Build states: (a,b,la,lb)
    # a,b in [0..n-1], la in [1..len[a]], lb in [1..len[b]]
    # state index mapping
    idx = {}
    states = []
    for a in range(n):
        for b in range(n):
            for la in range(1, lens[a]+1):
                for lb in range(1, lens[b]+1):
                    idx[(a,b,la,lb)] = len(states)
                    states.append((a,b,la,lb))
    S = len(states)

    # Precompute transitions
    T = [[0]*S for _ in range(S)]
    for s, (a,b,la,lb) in enumerate(states):
        # Determine possible next words for top and bottom
        tops = []
        bottoms = []

        # top next words
        if la < lens[a]:
            # continue same word
            tops.append((a, la+1))
        else:
            # la == len[a], can end word; next word must start with same char
            ch = words[a][0]
            for (L, c), lst in by_len_char.items():
                if c == ch:
                    for na in lst:
                        tops.append((na, 1))

        # bottom next words
        if lb < lens[b]:
            bottoms.append((b, lb+1))
        else:
            ch = words[b][0]
            for (L, c), lst in by_len_char.items():
                if c == ch:
                    for nb in lst:
                        bottoms.append((nb, 1))

        for na, nla in tops:
            for nb, nlb in bottoms:
                # check that the new letter is consistent
                # letter at position is words[na][nla-1] == words[nb][nlb-1]
                if words[na][nla-1] != words[nb][nlb-1]:
                    continue
                t = idx[(na, nb, nla, nlb)]
                T[s][t] = (T[s][t] + 1) % MOD

    if m == 0:
        print(0)
        return

    # initial vector: all states where la=lb=1 and first letters equal
    init = [0]*S
    for a in range(n):
        for b in range(n):
            if words[a][0] == words[b][0]:
                s = idx[(a,b,1,1)]
                init[s] = 1

    # exponentiate T^(m-1)
    if m == 1:
        vec = init
    else:
        Tpow = mat_pow(T, m-1)
        vec = [0]*S
        for i in range(S):
            if init[i]:
                ii = init[i]
                row = Tpow[i]
                for j in range(S):
                    vec[j] = (vec[j] + ii * row[j]) % MOD

    # sum over all states where la in pref[a] and lb in pref[b]
    ans = 0
    for s, (a,b,la,lb) in enumerate(states):
        if vec[s] == 0:
            continue
        if la in pref[a] and lb in pref[b]:
            ans = (ans + vec[s]) % MOD

    print(ans % MOD)

if __name__ == "__main__":
    main()
